// Cliente Contado Distribuidora: al elegirlo se habilita un campo
// para escribir el nombre real del comprador.
const CLIENTE_CONTADO = "C00879";

// Clientes cuyo nombre en SAP es la cedula juridica ("3102954865 SRL"). En el
// pedido solo se veria el numero, asi que se le pide al vendedor el nombre
// comercial y se manda en los comentarios.
// Un "nombre" solo sirve si no es basura: los pedidos de ventas aprobadas
// guardaron cosas como "(aprobada por correo@...)" en el campo del local, y
// eso salia en la hoja de ruta y en las etiquetas como si fuera el comercio.
// Quita las MARCAS internas que la app mete en los comentarios y que no son
// parte del nombre de nadie: "[Proforma PRO-123]", "VTA-456", "(aprobada
// por ...)". Se hace con cuidado de no tocar los guiones de adentro, porque
// los clientes de cedula juridica se llaman "3-101-123456".
const quitarMarcasComentario = (t) => String(t || "")
  .replace(/[\[(]\s*proforma[^\])]*[\])]?/gi, "")
  .replace(/\bVTA-\d+/g, "")
  .replace(/\bPRO-\d+/g, "")
  .replace(/\(?\s*aprobada\s+por[^)]*\)?/gi, "")
  .replace(/\s{2,}/g, " ")
  .replace(/^[\s\-·\[\]()]+|[\s\-·\[\]()]+$/g, "")
  .trim();

// Lo que bodega escribe en el campo del nombre cuando NO es un nombre.
// "AGREGADO" quiere decir que va dentro de otra caja -- es informacion util,
// pero no le dice al chofer a quien entregarle. Cuando aparece uno de estos,
// se descarta y se busca el nombre REAL de la venta.
const NO_ES_NOMBRE = [
  "AGREGADO","AGREGADOS","AGREGAR","SIN NOMBRE","SINNOMBRE","SN","NN",
  "NA","N/A","XX","XXX","PENDIENTE","CLIENTE","-","--","---",".",
];
const esPalabraDeRelleno = (v) => {
  const n = String(v||"")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toUpperCase().replace(/\s+/g, " ").trim();
  return NO_ES_NOMBRE.includes(n);
};

const nombreUtil = (t) => {
  // Se limpia ANTES de decidir: el nombre guardado en filas viejas puede
  // venir con la marca de la proforma pegada -- o ser SOLO esa marca, y
  // entonces no sirve como nombre y es mejor no mostrar nada.
  const v = quitarMarcasComentario(t);
  if(v.length < 3) return "";
  if(v.indexOf("@") >= 0) return "";
  if(/aprobada\s+por/i.test(v)) return "";
  // "AGREGADO" y compañia no son nombres: si se dejan pasar, tapan el nombre
  // real del cliente, que si esta guardado en la venta.
  if(esPalabraDeRelleno(v)) return "";
  return v;
};

// El nombre del cliente de CONTADO queda guardado dentro del campo cliente,
// como "Cliente Contado Distribuidora - HORACIO HOJANCHA". Para el pedido de
// SAP hay que sacarlo: sin el, en SAP solo queda "Cliente Contado" y nadie
// sabe a quien se le vendio.
const nombreRealDeVenta = (clienteTxt) => {
  const t = String(clienteTxt || "").trim();
  const i = t.indexOf(" - ");
  return i > 0 ? t.slice(i + 3).trim() : "";
};
const esNombreCedula = (nombre) => {
  const n = String(nombre||"").trim();
  if(!n) return false;
  return /^[0-9]/.test(n) && n.replace(/[^0-9]/g,"").length >= 9;
};

// Articulos que SAP NO deja vender con descuento. Al agregarlos al carrito se
// les fuerza 0%, aunque haya un descuento general puesto: asi el pedido no se
// rechaza por un descuento que el vendedor ni siquiera noto que aplicaba.
const SIN_DESCUENTO = ["BPR7ES","CR7HSA","CR8E","CPR8EA9","DPR8Z","CR8EH9"];
// Ademas de la lista fija, la app APRENDE: cada vez que SAP rechaza una venta
// por un articulo sin descuento, ese codigo se guarda aca y desde entonces se
// manda siempre en 0%. Asi no hace falta ir agregandolos a mano y una bujia
// nueva no vuelve a trabar toda la venta.
const SIN_DESC_KEY = "jci_sin_descuento_aprendidos";
const leerAprendidos = () => {
  try { const v = JSON.parse(localStorage.getItem(SIN_DESC_KEY) || "[]"); return Array.isArray(v) ? v : []; }
  catch(e){ return []; }
};
let SIN_DESC_APRENDIDOS = leerAprendidos();
const aprenderSinDescuento = (codigos) => {
  const nuevos = (codigos||[])
    .map(c => String(c||"").toUpperCase().trim())
    .filter(c => c && !SIN_DESCUENTO.includes(c) && !SIN_DESC_APRENDIDOS.includes(c));
  if(!nuevos.length) return [];
  SIN_DESC_APRENDIDOS = SIN_DESC_APRENDIDOS.concat(nuevos);
  try { localStorage.setItem(SIN_DESC_KEY, JSON.stringify(SIN_DESC_APRENDIDOS)); } catch(e){}
  return nuevos;
};
// Reglas de descuento por articulo, traidas de la tabla reglas_descuento.
// Se guardan aca para poder consultarlas desde cualquier parte sin pasarlas
// por props. Es un objeto { CODIGO: porcentaje }.
//   0            -> no lleva descuento
//   otro numero  -> lleva SIEMPRE ese porcentaje
//   sin regla    -> lo decide el vendedor
let REGLAS_DESC = {};
const fijarReglasDesc = (filas) => {
  const m = {};
  (filas||[]).forEach(r => {
    const c = String(r.codigo||"").toUpperCase().trim();
    if(c) m[c] = Number(r.pct) || 0;
  });
  REGLAS_DESC = m;
};
// Porcentaje obligado para un articulo, o null si es libre.
const descuentoObligado = (codigo) => {
  const c = String(codigo||"").toUpperCase().trim();
  if(!c) return null;
  if(REGLAS_DESC[c] != null) return REGLAS_DESC[c];
  // La lista vieja sigue valiendo: son articulos que SAP ya rechazo.
  if(SIN_DESCUENTO.includes(c) || SIN_DESC_APRENDIDOS.includes(c)) return 0;
  return null;
};
const noAdmiteDescuento = (codigo) => descuentoObligado(codigo) === 0;
// true si el vendedor NO puede tocar el campo (sea 0 o un porcentaje fijo)
const descuentoBloqueado = (codigo) => descuentoObligado(codigo) !== null;
// Saca los codigos que SAP menciono en el mensaje de error de descuento.
const codigosDelErrorDescuento = (texto) => {
  const t = String(texto||"");
  if(!/descuento/i.test(t)) return [];
  // El mensaje trae algo como "Articulos no pueden tener descuento: DPR8Z, CR8EH9"
  const m = t.match(/descuento[^:]*:\s*([^\n\r.]+)/i);
  if(!m) return [];
  return m[1].split(/[,;]+/).map(x => x.trim().toUpperCase()).filter(x => x && x.length <= 20);
};

// El usuario de Motopolis solo vende con el cliente de contado, eligiendo la tienda
const USUARIO_MOTOPOLIS = "motopolis@grupojcicr.com";
// QUE CUENTA COMO VENTA (19/10/2026): la MISMA regla en Reportes y en el
// Dashboard, para que los numeros cuadren. No cuentan las canceladas, los
// borradores ni las de prueba. (Motopolis se saca aparte en los totales
// generales, porque es tienda y no cartera.)
const ventaCuenta = (v) => !["cancelada","borrador"].includes(String((v && v.estado_sap) || "")) && !(v && v.es_prueba);
// Filtro equivalente para las consultas al servidor (totales generales)
const FILTRO_VENTAS_CUENTAN = "&and=" + encodeURIComponent("(or(estado_sap.is.null,estado_sap.not.in.(cancelada,borrador)),or(es_prueba.is.null,es_prueba.is.false))");
const FILTRO_VENTAS_GENERAL = FILTRO_VENTAS_CUENTAN + "&usuario_email=" + encodeURIComponent("not.eq." + USUARIO_MOTOPOLIS);
// Inicio de un dia de Costa Rica (UTC-6) como marca de tiempo para filtrar
// por fecha en el servidor. Antes se mandaba "2026-10-31" a secas, que la
// base lee como medianoche UTC (6 pm del dia anterior en CR): el ultimo dia
// del mes quedaba FUERA y las ventas de despues de las 6 pm caian en el dia
// siguiente.
const inicioDiaCR = (ymd) => ymd + "T00:00:00-06:00";
const ymdCR = (d) => { const x = new Date((d ? new Date(d) : new Date()).getTime() - 6 * 3600e3); return x.toISOString().slice(0, 10); };
const sumarDiasYmd = (ymd, n) => { const x = new Date(ymd + "T12:00:00Z"); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };
