// ===== RUTAS DE REPARTO =====
// Las zonas de la tabla de clientes vienen desparejas (a veces la direccion
// completa), asi que cada una se clasifica en una de estas rutas fijas.
const RUTAS_REPARTO = ["ENCOMIENDA","SAN JOSE","ALAJUELA CENTRO","ALAJUELA OCCIDENTE","HEREDIA","ACOSTA","CARTAGO","RECOGE EN DISTRIBUIDORA"];

// Como se identifica el destino de un pedido en bodega. Se basa en si el
// cliente TIENE encomienda, no en el campo "tipo": ese campo esta vacio en
// casi todos los clientes (la sincronizacion de SAP no lo llena) y por eso
// alistado y chequeo mostraban "SIN ZONA" aunque el cliente si tuviera su
// encomienda cargada.
// En SAP quedaron formas de envio DUPLICADAS: la misma encomienda con el
// numero de ruta ("#9 TRANSPORTES SERRANO") y sin el ("SERRANO"). Los
// clientes asignados a la version incompleta salian sin numero y el chofer
// no sabia por que ruta iba el paquete.
// Aca se completa: si la encomienda del cliente no trae numero, se busca
// entre las que SI lo tienen una que sea la misma y se usa esa.
const RELLENO_ENC = ["ENCOMIENDA","ENCOMIENDAS","TRANSPORTE","TRANSPORTES","EXPRESS","EXPRESO","DE","DEL","LA","EL","Y"];
const clavesEnc = (t) => String(t || "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .toUpperCase().replace(/#\s*\d+/g, " ").replace(/[^A-Z0-9 ]/g, " ")
  .split(/\s+/).filter(w => w && !RELLENO_ENC.includes(w));

// catalogo: se llena con todas las encomiendas CON numero que existan
let ENC_CON_NUMERO = [];
const fijarCatalogoEncomiendas = (filas) => {
  const vistas = new Set();
  ENC_CON_NUMERO = [];
  (filas || []).forEach((c) => {
    const t = String(c.encomienda || "").trim();
    if (!t || !/#\s*\d+/.test(t) || vistas.has(t)) return;
    vistas.add(t);
    ENC_CON_NUMERO.push({ texto: t, claves: clavesEnc(t) });
  });
};
// ENCOMIENDA DE UNA PARADA, respetando que la hayan movido a una zona.
//
// El dato vive en dos lados: empresa_encomienda (de la parada) y la
// encomienda del CLIENTE. Antes se leia "la de la parada o, si no, la del
// cliente". Al mover una parada de Encomienda a una zona se dejaba la de la
// parada vacia... y se caia a la del cliente, asi que reaparecia sola al
// despachar. En Pendientes se veia bien y en la hoja de ruta volvia
// "#1 TRANSPORTES EL MACHO".
//
// Al moverla se guarda tipo_envio = "gam". Con eso se sabe que esa parada ya
// NO va por mensajeria y no hay que buscarle ninguna.
// ESTADO DEL PEDIDO en el flujo (07/10/2026), para los reportes de Alistar y
// Chequear, con el mismo estilo de "pildora" que el reporte de Transporte.
const estadoFlujoPedido = (a) => {
  const ent = String((a && a.estado_entrega) || "").toLowerCase();
  const est = String((a && a.estado) || "").toLowerCase();
  if(ent === "entregado") return { txt: "ENTREGADO",    bg: "#eef7ea", fg: "#2f5527" };
  if(ent === "enviado" || ent === "en_ruta") return { txt: "EN RUTA", bg: "#fff4ed", fg: "#95440a" };
  if(ent === "agendado") return { txt: "AGENDADO",      bg: "#f0f9ff", fg: "#0c4a6e" };
  if(est === "facturado") return { txt: "FACTURADO",    bg: "#e0f2fe", fg: "#075985" };
  if(est === "chequeado") return { txt: "POR FACTURAR", bg: "#fef3c7", fg: "#92400e" };
  if(est === "completado") return { txt: "POR CHEQUEAR", bg: "#f3e8ff", fg: "#6b21a8" };
  if(est === "asignado") return { txt: "ALISTANDO",     bg: "#f1f5f9", fg: "#334155" };
  if(est === "omitido") return { txt: "OMITIDO",        bg: "#fee2e2", fg: "#991b1b" };
  if(est === "dividido") return { txt: "DIVIDIDO",      bg: "#f1f5f9", fg: "#475569" };
  return { txt: (est || "-").toUpperCase(), bg: "#f1f5f9", fg: "#475569" };
};
const PildoraEstado = ({ a }) => {
  const e = estadoFlujoPedido(a);
  return <span style={{fontSize:10.5,fontWeight:"bold",padding:"2px 8px",borderRadius:9,background:e.bg,color:e.fg,whiteSpace:"nowrap"}}>{e.txt}</span>;
};

const encomiendaDeParada = (a, dt) => {
  // SAP MANDA (07/10/2026). La encomienda es la de la ficha del cliente, que
  // se copia de SAP ("Forma de envio"). Lo que se haya escrito o guardado en
  // la parada (a mano, o al chequear) es solo un respaldo para cuando SAP no
  // tiene encomienda. Para cambiar la encomienda de un cliente, se cambia en SAP.
  if(!a) return "";
  const rm = String(a.ruta_manual || "").toUpperCase();
  // Movida a mano a una ruta de reparto propio (Acosta, San Jose...): esa
  // parada la lleva el camion, no lleva encomienda.
  if(rm && !rm.includes("ENCOMIENDA")) return "";
  // EXCEPCION PUNTUAL (07/10/2026): si alguien escribio otra encomienda en la
  // casilla de ESTE envio, se usa esa solo para este envio. SAP sigue igual
  // para los demas pedidos del cliente.
  if(a.encomienda_manual && String(a.empresa_encomienda || "").trim()) return a.empresa_encomienda;
  const deSap = dt && String(dt.encomienda || "").trim();
  if(deSap) return deSap;
  if(String(a.tipo_envio||"").toLowerCase() === "gam" && !rm) return "";
  return a.empresa_encomienda || "";
};
const encomiendaCompleta = (txt) => {
  const t = String(txt || "").trim();
  if (!t || /#\s*\d+/.test(t)) return t;      // ya trae numero
  const k = clavesEnc(t);
  if (!k.length) return t;
  // Se acepta solo si comparten TODAS las palabras propias: asi "SERRANO"
  // encuentra "#9 TRANSPORTES SERRANO" pero no se confunde con otra.
  const cal = ENC_CON_NUMERO.find((e) => k.every((w) => e.claves.includes(w)));
  return cal ? cal.texto : t;
};

// Igual que destinoDeCliente, pero respetando la ruta FIJADA A MANO del envio.
//
// destinoDeCliente decide "es encomienda" con un solo criterio: que la ficha
// del cliente tenga empresa de encomienda. Eso ignoraba por completo que
// alguien hubiera fijado el envio en SAN JOSE: el envio seguia rotulado y
// agrupado como encomienda, y terminaba en la hoja de encomiendas en vez de
// en la ruta de reparto.
const destinoDeEnvio = (a, dt) => {
  const fijada = (a && a.ruta_manual && RUTAS_REPARTO.includes(a.ruta_manual)) ? a.ruta_manual : "";
  if(fijada){
    // Se fijo a mano: manda esa ruta. Solo es encomienda si se fijo ahi.
    if(fijada.toUpperCase() === "ENCOMIENDA") return destinoDeCliente(dt);
    const zona = String((dt && dt.zona) || "").trim();
    return { texto: [fijada, zona].filter(Boolean).join(" · "), esEncomienda: false };
  }
  return destinoDeCliente(dt);
};

const destinoDeCliente = (dt) => {
  if(!dt) return { texto: "", esEncomienda: false };
  const enc = encomiendaCompleta(dt.encomienda);
  const zona = String(dt.zona || "").trim();
  if(enc) return { texto: [enc, zona].filter(Boolean).join(" · "), esEncomienda: true };
  return { texto: zona, esEncomienda: false };
};
// Credito o contado: lo decide el LIMITE DE CREDITO, que es lo que autoriza
// cuanto puede deber el cliente. Un plazo de 30 dias sin limite asignado no
// es un credito otorgado.
//
// Se probo decidirlo tambien por el plazo, para los 31 clientes que en SAP
// quedaron con limite en cero. Se revirtio a pedido del negocio: esos son
// contado de verdad y les van a asignar el limite en SAP cuando corresponda.
// Asi la app y SAP dicen lo mismo, y el limite sigue siendo el unico dato que
// autoriza credito.
const esClienteCredito = (c) => Number(c && c.limite_credito) > 0;
const etiquetaCredito = (c) => esClienteCredito(c)
  ? " · Credito" + (c.dias_credito ? " (" + c.dias_credito + " dias)" : "")
  : " · Contado";

// RETIRO EN BODEGA POR EL NOMBRE.
//
// Hay clientes cuyo nombre o local dice literalmente que pasan a traer el
// pedido ("RETIRA EN BODEGA", "RECOGE EN DISTRIBUIDORA"). Esos no salen a
// ruta, asi que su destino ya esta dicho y no hace falta buscarlos en la lista
// de clientes de transporte. Antes la pantalla decia "SIN ZONA · el cliente no
// esta en la lista de transporte", que asustaba sin motivo: al pedido no le
// falta nada.
const RE_RETIRA = /\b(RETIRA|RECOGE|PASA A TRAER)\b.*\b(BODEGA|DISTRIBUIDORA|LOCAL|TIENDA|SUCURSAL)\b/i;
const retiraEnBodega = (...textos) => textos.some(t => RE_RETIRA.test(
  String(t || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "")));

const rutaDeZona = (zona) => {
  const z = String(zona||"").toUpperCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g,"")
    .replace(/[^A-Z0-9 ]/g," ").replace(/\s+/g," ").trim();
  if(!z) return "SIN RUTA";
  const tiene = (...ps) => ps.some(x => z.includes(x));

  if(tiene("CARTAGO","PARAISO","TURRIALBA","OREAMUNO","TRES RIOS")) return "CARTAGO";
  if(tiene("HEREDIA","BELEN","SANTO DOMINGO","SAN JOAQUIN","BARVA","SANTA BARBARA","SAN RAFAEL HEREDIA")) return "HEREDIA";
  if(tiene("ACOSTA","LA FILA","SAN IGNACIO")) return "ACOSTA";
  // Occidente de Alajuela
  if(tiene("PALMARES","TURRUCARES","ATENAS","SAN RAMON","NARANJO","SARCHI","GRECIA","TACARES","TURRUBARES",
           "OROTINA","ZARCERO","PIEDADES SUR","ESPARZA","BARRANCA","PUNTARENAS","SAN MATEO"))
    return "ALAJUELA OCCIDENTE";
  // Alajuela centro: las zonas que reparte esa ruta (segun bodega)
  if(tiene("SAN RAFAEL","GUACIMA","GARITA","CARRILLOS","CARRILOS","BARRIO SAN JOSE","FRAIJANES",
           "SAN ISIDRO","CARRIZAL","SABANILLA","TUETAL","COYOL","ROBLE","POAS","CIRUELAS","CIRIELAS","CEIBA",
           "ALAJ CENTRO","RIO SEGUNDO"))
    return "ALAJUELA CENTRO";
  // Cualquier otra cosa que solo diga "Alajuela" tambien va al centro
  if(tiene("ALAJ","ALAJUELA")) return "ALAJUELA CENTRO";
  // San Jose y su area
  if(tiene("SAN JOSE","DESAMPARADOS","ASERRI","ALAJUELITA","ESCAZU","SANTA ANA","PAVAS","URUCA",
           "MORAVIA","TIBAS","GOICOECHEA","GUADALUPE","CURRIDABAT","SAN PEDRO","MONTES DE OCA",
           "HATILLO","SAN SEBASTIAN","ZAPOTE","CALLE BLANCOS","SABANA","CIUDAD COLON","PURISCAL",
           "MORA","TABARCIA","SANTIAGO","LEON CORTES","TARRAZU","FRAILES","CORRALILLO",
           "PURRISCAL"))   // mal escrito en varias fichas, se acepta igual
    return "SAN JOSE";
  // NO se cae a San Jose. Antes esta funcion terminaba con return "SAN JOSE",
  // asi que TODA zona que no reconociera -- mal escrita, con la direccion
  // entera metida en el campo, o de un lugar que nadie puso en las listas de
  // arriba -- terminaba en la ruta de San Jose sin que nadie se enterara. Por
  // eso el filtro de San Jose salia revuelto con envios de Alajuela y de otras
  // partes: el filtro estaba bien, la clasificacion mandaba ahi lo que no
  // entendia. Ahora cae en SIN RUTA, que se ve al final y se puede corregir.
  return "SIN RUTA";
};

