// Copia de como vienen las listas en el codigo (para activar y como respaldo)
const PERMISOS_CODIGO = Object.fromEntries(CATALOGO_PERMISOS.map(p => [p.k, p.lista.map(e => String(e).toLowerCase())]));
// Llena las listas con lo que dice la tabla. Si la tabla no esta activada
// (no tiene la marca __sistema__/activo), se quedan las del codigo.
const aplicarPermisos = (filas) => {
  const activo = (filas || []).some(f => f.email === "__sistema__" && f.permiso === "activo");
  CATALOGO_PERMISOS.forEach(p => {
    const nuevos = activo
      ? (filas || []).filter(f => f.permiso === p.k).map(f => String(f.email).toLowerCase())
      : PERMISOS_CODIGO[p.k];
    p.lista.splice(0, p.lista.length, ...new Set(nuevos));
  });
  SUPER_ADMINS_USUARIOS.forEach(e => { if(!PERM_USUARIOS.includes(e)) PERM_USUARIOS.push(e); });
  const todos = new Set(USUARIOS_SIMULABLES);
  CATALOGO_PERMISOS.forEach(p => p.lista.forEach(e => { if(String(e).includes("@")) todos.add(e); }));
  USUARIOS_SIMULABLES.splice(0, USUARIOS_SIMULABLES.length, ...[...todos].sort());
  return activo;
};
