  //    persona esta en Facturar, la lista se refresca sola.
  //  - ALMACEN: una solicitud de picking nueva (o una devolucion).
  //  - PICKING: almacen le mando algo para revisar.
  // La primera lectura solo toma la foto: no suena por lo que ya habia.
  // El navegador solo deja sonar despues de que la persona toco la pantalla
  // una vez; por eso el sonido se "despierta" con el primer toque.
  const audioCtxRef = useRef(null);
  useEffect(() => {
    const despertar = () => {
      try {
        if(!audioCtxRef.current){
          const AC = window.AudioContext || window.webkitAudioContext;
          if(AC) audioCtxRef.current = new AC();
        }
        if(audioCtxRef.current && audioCtxRef.current.state === "suspended") audioCtxRef.current.resume();
      } catch(e){}
    };
    window.addEventListener("pointerdown", despertar);
    window.addEventListener("keydown", despertar);
    return () => { window.removeEventListener("pointerdown", despertar); window.removeEventListener("keydown", despertar); };
  }, []);
  const sonarAviso = () => {
    try {
      const ctx = audioCtxRef.current;
      if(!ctx) return;
      const t0 = ctx.currentTime;
      [[880, 0], [1175, 0.18], [1568, 0.36]].forEach(([f, dt]) => {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = "sine"; o.frequency.value = f;
        g.gain.setValueAtTime(0.0001, t0 + dt);
        g.gain.exponentialRampToValueAtTime(0.35, t0 + dt + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, t0 + dt + 0.16);
        o.connect(g); g.connect(ctx.destination);
        o.start(t0 + dt); o.stop(t0 + dt + 0.18);
      });
    } catch(e){}
  };
