  const proformasVeTodas = puede(miEmail, ["msirias90@gmail.com","e.espinoza@grupojcicr.com","jc.sandoval@grupojcicr.com"]);
  const canViaticos = !!miEmail && !soloBodega && !sinExtras;
  // Estos correos ven los viaticos de TODOS los vendedores; el resto solo los suyos
  const viaticosVeTodos = puede(miEmail, ["msirias90@gmail.com","e.espinoza@grupojcicr.com","jc.sandoval@grupojcicr.com","r.lemaitre@grupojcicr.com","k.sandoval@grupojcicr.com","w.valverde@grupojcicr.com","k.bravo@grupojcicr.com"]);
  const showToast = (msg,type="success") => { setToast({msg,type}); setTimeout(()=>setToast(null),3500); };

  // Detecta si un error es por sesion vencida. Si lo es, cierra sesion y avisa.
  const esSesionVencida = (err) => {
    const m = (err && err.message ? err.message : String(err||"")).toLowerCase();
    return m.includes("jwt expired") || m.includes("jwt expir") || (m.includes("token") && m.includes("expir"));
  };
  const manejarSesionVencida = () => {
    setSession(null); setRol(null);
    setSessionMsg("Tu sesion expiro. Por favor inicia sesion nuevamente.");
  };

  // Renueva el access_token usando el refresh_token, para que la sesion no expire
  // mientras la app este abierta. Supabase vence el token de acceso en ~1 hora.
  const refrescarToken = async () => {
    const rt = (sessionRef.current && sessionRef.current.refresh_token) || session?.refresh_token;
    if(!rt) return;
    try {
      const res = await fetch(SUPABASE_URL+"/auth/v1/token?grant_type=refresh_token", {
        method:"POST",
        headers:{"Content-Type":"application/json","apikey":SUPABASE_KEY},
        body:JSON.stringify({ refresh_token: rt })
      });
      if(!res.ok) return; // si falla, no rompemos nada; el manejo de sesion vencida sigue activo
      const nueva = await res.json();
      if(nueva && nueva.access_token){
        // conservamos user/rol; solo actualizamos tokens
        setSession(prev => ({ ...prev, ...nueva }));
      }
    } catch(e) { /* silencioso: si no se pudo renovar, se intenta en el proximo ciclo */ }
  };

  const handleLogin = async (data) => {
    setAuthLoading(true);
    try { const token=data.access_token; const userId=data.user.id; const rows=await authFetch("usuarios?id=eq."+userId+"&select=rol","GET",null,token); setSession(data); setRol(rows[0]?.rol||"viewer"); }
    catch { setSession(data); setRol("viewer"); }
    setAuthLoading(false);
  };

  const handleLogout = async () => { if(session?.access_token)await signOut(session.access_token); setSession(null);setRol(null); };

  // ---- TITULO DEL WHATSAPP DE LA HOJA DE RUTA (19/10/2026) ----
  // Antes de mandar la hoja al grupo, quien despacha escribe el titulo que
