    18:"CARLOS SAENZ", 19:"CARLOS SAENZ - FRANCISCO", 20:"DISTRIBUIDORA - FRANCISCO",
    21:"KENER - FRANCISCO", 22:"NINGUNO", 23:"OSVALDO SANCHO", 24:"CARLOS MONTIEL",
